def conjugate(verb: str) -> dict:
    suffix_map = {
        'ar': ['o', 'as', 'a', 'amos', 'áis', 'an'],
        'er': ['o', 'es', 'e', 'emos', 'éis', 'en'],
        'ir': ['o', 'es', 'e', 'imos', 'ís', 'en']
    }

    if verb.endswith('ar'):
        base = verb[:-2]
        suffixes = suffix_map['ar']
    elif verb.endswith('er'):
        base = verb[:-2]
        suffixes = suffix_make_er_ir(base, suffix_map['er'])
    elif verb.endswith('ir'):
        base = verb[:-2]
        suffixes = suffixes = suffix_map['ir']
    else:
        raise ValueError("Verb must end with ar, er, or ir")

    conjugations = [base + suf for suf in suffixes]

    return {verb: conjugations}

